/* ============================================================================
 * YUKA — Game AI Library for Three.js (js/libs/yuka.min.js)
 * Autonomous Agent Steering, Perception/Vision, Memory, NavMesh, FSM,
 * Goal-Driven Arbitration (Think / GoalEvaluator), and Three.js SyncManager.
 * ============================================================================ */
(function (global) {
    'use strict';

    class Vector3 {
        constructor(x = 0, y = 0, z = 0) {
            this.x = x;
            this.y = y;
            this.z = z;
        }
        set(x, y, z) {
            this.x = x;
            this.y = y;
            this.z = z;
            return this;
        }
        copy(v) {
            this.x = v.x;
            this.y = v.y;
            this.z = v.z;
            return this;
        }
        clone() {
            return new Vector3(this.x, this.y, this.z);
        }
        add(v) {
            this.x += v.x;
            this.y += v.y;
            this.z += v.z;
            return this;
        }
        sub(v) {
            this.x -= v.x;
            this.y -= v.y;
            this.z -= v.z;
            return this;
        }
        subVectors(a, b) {
            this.x = a.x - b.x;
            this.y = a.y - b.y;
            this.z = a.z - b.z;
            return this;
        }
        addVectors(a, b) {
            this.x = a.x + b.x;
            this.y = a.y + b.y;
            this.z = a.z + b.z;
            return this;
        }
        multiplyScalar(s) {
            this.x *= s;
            this.y *= s;
            this.z *= s;
            return this;
        }
        divideScalar(s) {
            if (s !== 0) {
                this.x /= s;
                this.y /= s;
                this.z /= s;
            } else {
                this.x = 0; this.y = 0; this.z = 0;
            }
            return this;
        }
        dot(v) {
            return this.x * v.x + this.y * v.y + this.z * v.z;
        }
        crossVectors(a, b) {
            const ax = a.x, ay = a.y, az = a.z;
            const bx = b.x, by = b.y, bz = b.z;
            this.x = ay * bz - az * by;
            this.y = az * bx - ax * bz;
            this.z = ax * by - ay * bx;
            return this;
        }
        squaredLength() {
            return this.x * this.x + this.y * this.y + this.z * this.z;
        }
        length() {
            return Math.sqrt(this.squaredLength());
        }
        squaredDistanceTo(v) {
            const dx = this.x - v.x, dy = this.y - v.y, dz = this.z - v.z;
            return dx * dx + dy * dy + dz * dz;
        }
        distanceTo(v) {
            return Math.sqrt(this.squaredDistanceTo(v));
        }
        normalize() {
            return this.divideScalar(this.length() || 1);
        }
        clampLength(min, max) {
            const length = this.length();
            return this.divideScalar(length || 1).multiplyScalar(Math.max(min, Math.min(max, length)));
        }
    }

    class Quaternion {
        constructor(x = 0, y = 0, z = 0, w = 1) {
            this.x = x; this.y = y; this.z = z; this.w = w;
        }
        set(x, y, z, w) {
            this.x = x; this.y = y; this.z = z; this.w = w;
            return this;
        }
        copy(q) {
            this.x = q.x; this.y = q.y; this.z = q.z; this.w = q.w;
            return this;
        }
        clone() {
            return new Quaternion(this.x, this.y, this.z, this.w);
        }
        fromEuler(x, y, z) {
            const c1 = Math.cos(x / 2), c2 = Math.cos(y / 2), c3 = Math.cos(z / 2);
            const s1 = Math.sin(x / 2), s2 = Math.sin(y / 2), s3 = Math.sin(z / 2);
            this.x = s1 * c2 * c3 + c1 * s2 * s3;
            this.y = c1 * s2 * c3 - s1 * c2 * s3;
            this.z = c1 * c2 * s3 + s1 * s2 * c3;
            this.w = c1 * c2 * c3 - s1 * s2 * s3;
            return this;
        }
        lookAt(forward, direction, up) {
            const yaw = Math.atan2(direction.x, direction.z);
            this.fromEuler(0, yaw, 0);
            return this;
        }
    }

    class Path {
        constructor() {
            this.loop = false;
            this._waypoints = [];
            this._index = 0;
        }
        add(waypoint) {
            this._waypoints.push(waypoint.clone ? waypoint.clone() : new Vector3(waypoint.x, waypoint.y, waypoint.z));
            return this;
        }
        clear() {
            this._waypoints.length = 0;
            this._index = 0;
            return this;
        }
        current() {
            return this._waypoints[this._index] || null;
        }
        finished() {
            if (this._waypoints.length === 0) return true;
            return this.loop ? false : (this._index >= this._waypoints.length - 1);
        }
        advance() {
            this._index++;
            if (this._index >= this._waypoints.length) {
                if (this.loop) {
                    this._index = 0;
                } else {
                    this._index = Math.max(0, this._waypoints.length - 1);
                }
            }
            return this;
        }
    }

    let _nextEntityUuid = 1;

    class GameEntity {
        constructor() {
            this.uuid = 'yuka-entity-' + (_nextEntityUuid++);
            this.name = '';
            this.active = true;
            this.position = new Vector3();
            this.rotation = new Quaternion();
            this.scale = new Vector3(1, 1, 1);
            this.forward = new Vector3(0, 0, 1);
            this.up = new Vector3(0, 1, 0);
            this.boundingRadius = 1.0;
            this.maxTurnRate = Math.PI;
            this.updateNeighborhood = false;
            this.neighborhoodRadius = 5.0;
            this.neighbors = [];
            this.manager = null;
            this._renderComponent = null;
            this._renderComponentCallback = null;
            this.userData = {};
        }
        setRenderComponent(renderComponent, callback) {
            this._renderComponent = renderComponent;
            this._renderComponentCallback = callback || SyncManager.sync;
            return this;
        }
        getDirection(result = new Vector3()) {
            return result.copy(this.forward).normalize();
        }
        lookAt(target) {
            const dx = target.x - this.position.x;
            const dz = target.z - this.position.z;
            const len = Math.hypot(dx, dz);
            if (len > 1e-5) {
                this.forward.set(dx / len, 0, dz / len);
                this.rotation.lookAt(new Vector3(0, 0, 1), this.forward, this.up);
            }
            return this;
        }
        start() {}
        update(/* delta */) {}
    }

    class MovingEntity extends GameEntity {
        constructor() {
            super();
            this.velocity = new Vector3();
            this.maxSpeed = 7.5;
            this.updateOrientation = true;
        }
        getSpeed() {
            return this.velocity.length();
        }
        getSpeedSquared() {
            return this.velocity.squaredLength();
        }
        update(delta) {
            if (this.updateOrientation && this.velocity.squaredLength() > 1e-4) {
                const targetPos = new Vector3().addVectors(this.position, this.velocity);
                this.lookAt(targetPos);
            }
            return this;
        }
    }

    class SteeringBehavior {
        constructor() {
            this.weight = 1.0;
            this.active = true;
        }
        calculate(/* vehicle, force, delta */) {}
    }

    class SeekBehavior extends SteeringBehavior {
        constructor(target = new Vector3()) {
            super();
            this.target = target;
        }
        calculate(vehicle, force) {
            const desired = new Vector3().subVectors(this.target, vehicle.position);
            if (desired.squaredLength() > 1e-6) {
                desired.normalize().multiplyScalar(vehicle.maxSpeed);
                force.subVectors(desired, vehicle.velocity);
            }
            return force;
        }
    }

    class FleeBehavior extends SteeringBehavior {
        constructor(target = new Vector3(), panicDistance = 10) {
            super();
            this.target = target;
            this.panicDistance = panicDistance;
        }
        calculate(vehicle, force) {
            const distSq = vehicle.position.squaredDistanceTo(this.target);
            if (distSq <= this.panicDistance * this.panicDistance) {
                const desired = new Vector3().subVectors(vehicle.position, this.target);
                if (desired.squaredLength() > 1e-6) {
                    desired.normalize().multiplyScalar(vehicle.maxSpeed);
                } else {
                    desired.set(1, 0, 0).multiplyScalar(vehicle.maxSpeed);
                }
                force.subVectors(desired, vehicle.velocity);
            }
            return force;
        }
    }

    class ArriveBehavior extends SteeringBehavior {
        constructor(target = new Vector3(), deceleration = 2.5, tolerance = 0.25) {
            super();
            this.target = target;
            this.deceleration = deceleration;
            this.tolerance = tolerance;
        }
        calculate(vehicle, force) {
            const toTarget = new Vector3().subVectors(this.target, vehicle.position);
            const distance = toTarget.length();
            if (distance > this.tolerance) {
                let speed = distance / Math.max(0.2, this.deceleration);
                speed = Math.min(speed, vehicle.maxSpeed);
                const desiredVelocity = toTarget.multiplyScalar(speed / distance);
                force.subVectors(desiredVelocity, vehicle.velocity);
            } else {
                force.copy(vehicle.velocity).multiplyScalar(-1);
            }
            return force;
        }
    }

    class PursueBehavior extends SteeringBehavior {
        constructor(evader = null, predictionFactor = 1.0) {
            super();
            this.evader = evader;
            this.predictionFactor = predictionFactor;
            this._seek = new SeekBehavior();
        }
        calculate(vehicle, force) {
            if (!this.evader) return force;
            const displacement = new Vector3().subVectors(this.evader.position, vehicle.position);
            const distance = displacement.length();
            const speed = vehicle.getSpeed();
            let lookAheadTime = (speed <= distance / this.predictionFactor)
                ? this.predictionFactor
                : (distance / Math.max(0.5, speed)) * this.predictionFactor;
            lookAheadTime = Math.min(0.65, lookAheadTime);

            this._seek.target.copy(this.evader.velocity).multiplyScalar(lookAheadTime).add(this.evader.position);
            this._seek.calculate(vehicle, force);
            return force;
        }
    }

    class EvadeBehavior extends SteeringBehavior {
        constructor(pursuer = null, panicDistance = 10, predictionFactor = 1.0) {
            super();
            this.pursuer = pursuer;
            this.panicDistance = panicDistance;
            this.predictionFactor = predictionFactor;
            this._flee = new FleeBehavior(new Vector3(), panicDistance);
        }
        calculate(vehicle, force) {
            if (!this.pursuer) return force;
            const displacement = new Vector3().subVectors(this.pursuer.position, vehicle.position);
            const distance = displacement.length();
            const speed = this.pursuer.getSpeed ? this.pursuer.getSpeed() : 6.0;
            const lookAheadTime = Math.min(0.6, (distance / Math.max(1.0, speed)) * this.predictionFactor);

            this._flee.panicDistance = this.panicDistance;
            this._flee.target.copy(this.pursuer.velocity).multiplyScalar(lookAheadTime).add(this.pursuer.position);
            this._flee.calculate(vehicle, force);
            return force;
        }
    }

    class WanderBehavior extends SteeringBehavior {
        constructor(radius = 1.5, distance = 3.0, jitter = 2.0) {
            super();
            this.radius = radius;
            this.distance = distance;
            this.jitter = jitter;
            const theta = Math.random() * Math.PI * 2;
            this._wanderTarget = new Vector3(Math.cos(theta) * radius, 0, Math.sin(theta) * radius);
        }
        calculate(vehicle, force, delta = 0.016) {
            const jitterThisStep = this.jitter * delta;
            this._wanderTarget.x += (Math.random() * 2 - 1) * jitterThisStep;
            this._wanderTarget.y += (Math.random() * 2 - 1) * jitterThisStep * 0.25;
            this._wanderTarget.z += (Math.random() * 2 - 1) * jitterThisStep;
            this._wanderTarget.normalize().multiplyScalar(this.radius);

            const targetWorld = new Vector3()
                .copy(vehicle.forward)
                .multiplyScalar(this.distance)
                .add(vehicle.position)
                .add(this._wanderTarget);
            force.subVectors(targetWorld, vehicle.position);
            return force;
        }
    }

    class SeparationBehavior extends SteeringBehavior {
        constructor() {
            super();
        }
        calculate(vehicle, force) {
            const neighbors = vehicle.neighbors;
            for (let i = 0; i < neighbors.length; i++) {
                const neighbor = neighbors[i];
                if (neighbor === vehicle) continue;
                const toAgent = new Vector3().subVectors(vehicle.position, neighbor.position);
                const length = toAgent.length();
                if (length > 1e-4) {
                    toAgent.normalize().divideScalar(length);
                    force.add(toAgent);
                }
            }
            return force;
        }
    }

    class AlignmentBehavior extends SteeringBehavior {
        constructor() {
            super();
        }
        calculate(vehicle, force) {
            const neighbors = vehicle.neighbors;
            if (neighbors.length === 0) return force;
            const avgDirection = new Vector3();
            let count = 0;
            for (let i = 0; i < neighbors.length; i++) {
                const neighbor = neighbors[i];
                if (neighbor === vehicle) continue;
                avgDirection.add(neighbor.forward);
                count++;
            }
            if (count > 0) {
                avgDirection.divideScalar(count);
                force.subVectors(avgDirection, vehicle.forward);
            }
            return force;
        }
    }

    class CohesionBehavior extends SteeringBehavior {
        constructor() {
            super();
            this._seek = new SeekBehavior();
        }
        calculate(vehicle, force) {
            const neighbors = vehicle.neighbors;
            if (neighbors.length === 0) return force;
            const centerOfMass = new Vector3();
            let count = 0;
            for (let i = 0; i < neighbors.length; i++) {
                const neighbor = neighbors[i];
                if (neighbor === vehicle) continue;
                centerOfMass.add(neighbor.position);
                count++;
            }
            if (count > 0) {
                centerOfMass.divideScalar(count);
                this._seek.target.copy(centerOfMass);
                this._seek.calculate(vehicle, force);
                force.normalize();
            }
            return force;
        }
    }

    class ObstacleAvoidanceBehavior extends SteeringBehavior {
        constructor(obstacles = []) {
            super();
            this.obstacles = obstacles;
            this.dBoxMinLength = 3.0;
            this.brakingWeight = 0.2;
        }
        calculate(vehicle, force) {
            if (!this.obstacles || this.obstacles.length === 0) return force;
            const dBoxLength = this.dBoxMinLength + (vehicle.getSpeed() / Math.max(1, vehicle.maxSpeed)) * this.dBoxMinLength;
            for (let i = 0; i < this.obstacles.length; i++) {
                const obs = this.obstacles[i];
                const obsPos = obs.position || obs;
                const obsRad = (obs.boundingRadius || obs.radius || 1.2) + vehicle.boundingRadius;
                const toObs = new Vector3().subVectors(obsPos, vehicle.position);
                const dist = toObs.length();
                if (dist < dBoxLength + obsRad && dist > 1e-4) {
                    const push = new Vector3().subVectors(vehicle.position, obsPos).normalize();
                    const strength = Math.max(0.2, 1.0 - dist / (dBoxLength + obsRad));
                    force.add(push.multiplyScalar(vehicle.maxForce * strength * 1.5));
                }
            }
            return force;
        }
    }

    class FollowPathBehavior extends SteeringBehavior {
        constructor(path = new Path(), nextWaypointDistance = 1.0) {
            super();
            this.path = path;
            this.nextWaypointDistance = nextWaypointDistance;
            this._seek = new SeekBehavior();
            this._arrive = new ArriveBehavior();
        }
        calculate(vehicle, force) {
            const path = this.path;
            const current = path.current();
            if (!current) return force;
            const distSq = current.squaredDistanceTo(vehicle.position);
            if (distSq < this.nextWaypointDistance * this.nextWaypointDistance) {
                path.advance();
            }
            const target = path.current();
            if (!target) return force;
            if (!path.finished()) {
                this._seek.target.copy(target);
                this._seek.calculate(vehicle, force);
            } else {
                this._arrive.target.copy(target);
                this._arrive.calculate(vehicle, force);
            }
            return force;
        }
    }

    class SteeringManager {
        constructor(vehicle) {
            this.vehicle = vehicle;
            this.behaviors = [];
            this._steeringForce = new Vector3();
        }
        add(behavior) {
            this.behaviors.push(behavior);
            return this;
        }
        remove(behavior) {
            const idx = this.behaviors.indexOf(behavior);
            if (idx !== -1) this.behaviors.splice(idx, 1);
            return this;
        }
        clear() {
            this.behaviors.length = 0;
            return this;
        }
        calculate(delta, result = new Vector3()) {
            result.set(0, 0, 0);
            const force = new Vector3();
            for (let i = 0; i < this.behaviors.length; i++) {
                const behavior = this.behaviors[i];
                if (behavior.active && behavior.weight > 0) {
                    force.set(0, 0, 0);
                    behavior.calculate(this.vehicle, force, delta);
                    force.multiplyScalar(behavior.weight);
                    result.add(force);
                    if (result.squaredLength() > this.vehicle.maxForce * this.vehicle.maxForce) {
                        result.clampLength(0, this.vehicle.maxForce);
                        break;
                    }
                }
            }
            return result;
        }
    }

    class Vehicle extends MovingEntity {
        constructor() {
            super();
            this.mass = 1.0;
            this.maxForce = 25.0;
            this.steering = new SteeringManager(this);
            this._steeringForce = new Vector3();
        }
        update(delta) {
            this.steering.calculate(delta, this._steeringForce);
            const acceleration = this._steeringForce.divideScalar(Math.max(0.05, this.mass));
            this.velocity.add(acceleration.multiplyScalar(delta));
            this.velocity.clampLength(0, this.maxSpeed);
            this.position.add(new Vector3().copy(this.velocity).multiplyScalar(delta));
            super.update(delta);
            return this;
        }
    }

    class Vision {
        constructor(owner = null) {
            this.owner = owner;
            this.fieldOfView = Math.PI;
            this.range = Infinity;
            this.obstacles = [];
        }
        visible(point) {
            if (!this.owner) return true;
            const toPoint = new Vector3().subVectors(point, this.owner.position);
            const distSq = toPoint.squaredLength();
            if (distSq > this.range * this.range) return false;
            if (distSq > 1e-6) {
                toPoint.normalize();
                const cosAngle = this.owner.forward.dot(toPoint);
                if (cosAngle < Math.cos(this.fieldOfView * 0.5)) return false;
            }
            return true;
        }
    }

    class MemoryRecord {
        constructor(entity = null) {
            this.entity = entity;
            this.timeBecameVisible = -Infinity;
            this.timeLastSensed = -Infinity;
            this.lastSensedPosition = new Vector3();
            this.visible = false;
        }
    }

    class MemorySystem {
        constructor(owner = null) {
            this.owner = owner;
            this.records = [];
            this.recordsMap = new Map();
            this.memorySpan = 3.5;
        }
        createRecord(entity) {
            const record = new MemoryRecord(entity);
            this.records.push(record);
            this.recordsMap.set(entity, record);
            return record;
        }
        getRecord(entity) {
            return this.recordsMap.get(entity) || null;
        }
        hasRecord(entity) {
            return this.recordsMap.has(entity);
        }
        getValidMemoryRecords(currentTime, result = []) {
            result.length = 0;
            for (let i = 0; i < this.records.length; i++) {
                const record = this.records[i];
                if (currentTime - record.timeLastSensed <= this.memorySpan) {
                    result.push(record);
                }
            }
            return result;
        }
    }

    class State {
        enter(/* owner */) {}
        execute(/* owner */) {}
        exit(/* owner */) {}
    }

    class StateMachine {
        constructor(owner = null) {
            this.owner = owner;
            this.currentState = null;
            this.previousState = null;
            this.globalState = null;
            this.states = new Map();
        }
        add(id, state) {
            this.states.set(id, state);
            return this;
        }
        changeTo(idOrState) {
            const nextState = typeof idOrState === 'string' ? this.states.get(idOrState) : idOrState;
            if (!nextState || nextState === this.currentState) return this;
            this.previousState = this.currentState;
            if (this.currentState && this.currentState.exit) this.currentState.exit(this.owner);
            this.currentState = nextState;
            if (this.currentState && this.currentState.enter) this.currentState.enter(this.owner);
            return this;
        }
        revert() {
            if (this.previousState) this.changeTo(this.previousState);
            return this;
        }
        update() {
            if (this.globalState && this.globalState.execute) this.globalState.execute(this.owner);
            if (this.currentState && this.currentState.execute) this.currentState.execute(this.owner);
            return this;
        }
    }

    const GoalStatus = Object.freeze({
        INACTIVE: 'inactive',
        ACTIVE: 'active',
        COMPLETED: 'completed',
        FAILED: 'failed'
    });

    class Goal {
        constructor(owner = null) {
            this.owner = owner;
            this.status = GoalStatus.INACTIVE;
        }
        activate() {}
        execute() {}
        terminate() {}
        activateIfInactive() {
            if (this.inactive()) {
                this.status = GoalStatus.ACTIVE;
                this.activate();
            }
        }
        inactive() { return this.status === GoalStatus.INACTIVE; }
        active() { return this.status === GoalStatus.ACTIVE; }
        completed() { return this.status === GoalStatus.COMPLETED; }
        failed() { return this.status === GoalStatus.FAILED; }
    }

    class CompositeGoal extends Goal {
        constructor(owner = null) {
            super(owner);
            this.subgoals = [];
        }
        addSubgoal(goal) {
            this.subgoals.unshift(goal);
            return this;
        }
        clearSubgoals() {
            for (let i = 0; i < this.subgoals.length; i++) {
                this.subgoals[i].terminate();
            }
            this.subgoals.length = 0;
            return this;
        }
        currentSubgoal() {
            return this.subgoals.length > 0 ? this.subgoals[0] : null;
        }
        executeSubgoals() {
            while (this.subgoals.length > 0) {
                const subgoal = this.subgoals[0];
                if (subgoal.completed() || subgoal.failed()) {
                    subgoal.terminate();
                    this.subgoals.shift();
                } else {
                    break;
                }
            }
            if (this.subgoals.length > 0) {
                const subgoal = this.subgoals[0];
                subgoal.activateIfInactive();
                subgoal.execute();
                if (subgoal.completed() && this.subgoals.length > 1) {
                    return GoalStatus.ACTIVE;
                }
                return subgoal.status;
            }
            return GoalStatus.COMPLETED;
        }
    }

    class GoalEvaluator {
        constructor(characterBias = 1.0) {
            this.characterBias = characterBias;
        }
        calculateDesirability(/* owner */) { return 0; }
        setGoal(/* owner */) {}
    }

    class Think extends CompositeGoal {
        constructor(owner = null) {
            super(owner);
            this.evaluators = [];
            this.activeEvaluator = null;
        }
        addEvaluator(evaluator) {
            this.evaluators.push(evaluator);
            return this;
        }
        arbitrate() {
            let bestDesirability = -1;
            let bestEvaluator = null;
            for (let i = 0; i < this.evaluators.length; i++) {
                const evaluator = this.evaluators[i];
                const desirability = evaluator.calculateDesirability(this.owner) * evaluator.characterBias;
                if (desirability >= bestDesirability) {
                    bestDesirability = desirability;
                    bestEvaluator = evaluator;
                }
            }
            if (bestEvaluator) {
                this.activeEvaluator = bestEvaluator;
                bestEvaluator.setGoal(this.owner);
            }
            return bestEvaluator;
        }
        execute() {
            this.activateIfInactive();
            const subgoalStatus = this.executeSubgoals();
            if (subgoalStatus === GoalStatus.COMPLETED || subgoalStatus === GoalStatus.FAILED) {
                this.status = GoalStatus.INACTIVE;
            }
        }
    }

    class NavMesh {
        constructor() {
            this.regions = [];
            this.nodes = [];
        }
        fromTerrainFunction(minX, maxX, stepX, getGroundHeightFn) {
            this.regions.length = 0;
            this.nodes.length = 0;
            for (let x = minX; x <= maxX; x += stepX) {
                const y = getGroundHeightFn(x, 0);
                const nextX = Math.min(maxX, x + stepX);
                const nextY = getGroundHeightFn(nextX, 0);
                const slope = Math.atan2(nextY - y, Math.max(0.01, nextX - x));
                this.nodes.push({
                    x,
                    y,
                    z: 0,
                    slope,
                    cost: 1.0 + Math.abs(slope) * 0.8
                });
            }
            return this;
        }
        findPath(from, to) {
            const startX = typeof from === 'number' ? from : from.x;
            const endX = typeof to === 'number' ? to : to.x;
            const path = [];
            if (this.nodes.length === 0) {
                path.push(new Vector3(startX, 0, 0), new Vector3(endX, 0, 0));
                return path;
            }
            const dir = endX >= startX ? 1 : -1;
            for (let i = 0; i < this.nodes.length; i++) {
                const n = this.nodes[dir === 1 ? i : (this.nodes.length - 1 - i)];
                if ((dir === 1 && n.x >= startX && n.x <= endX) || (dir === -1 && n.x <= startX && n.x >= endX)) {
                    path.push(new Vector3(n.x, n.y, n.z));
                }
            }
            if (path.length === 0) {
                path.push(new Vector3(endX, 0, 0));
            }
            return path;
        }
    }

    class EntityManager {
        constructor() {
            this.entities = [];
        }
        add(entity) {
            if (this.entities.indexOf(entity) === -1) {
                this.entities.push(entity);
                entity.manager = this;
                entity.start();
            }
            return this;
        }
        remove(entity) {
            const index = this.entities.indexOf(entity);
            if (index !== -1) {
                this.entities.splice(index, 1);
                entity.manager = null;
            }
            return this;
        }
        clear() {
            this.entities.length = 0;
            return this;
        }
        updateNeighborhood(entity) {
            entity.neighbors.length = 0;
            const rSq = entity.neighborhoodRadius * entity.neighborhoodRadius;
            for (let i = 0; i < this.entities.length; i++) {
                const other = this.entities[i];
                if (other !== entity && other.active) {
                    if (entity.position.squaredDistanceTo(other.position) <= rSq) {
                        entity.neighbors.push(other);
                    }
                }
            }
        }
        update(delta) {
            for (let i = 0; i < this.entities.length; i++) {
                const entity = this.entities[i];
                if (entity.active) {
                    if (entity.updateNeighborhood) {
                        this.updateNeighborhood(entity);
                    }
                    entity.update(delta);
                    if (entity._renderComponent && entity._renderComponentCallback) {
                        entity._renderComponentCallback(entity, entity._renderComponent);
                    }
                }
            }
            return this;
        }
    }

    const SyncManager = {
        sync(entity, renderComponent) {
            if (!renderComponent) return;
            if (renderComponent.position) {
                renderComponent.position.set(entity.position.x, entity.position.y, entity.position.z);
            }
            if (renderComponent.quaternion && entity.updateOrientation) {
                renderComponent.quaternion.set(
                    entity.rotation.x,
                    entity.rotation.y,
                    entity.rotation.z,
                    entity.rotation.w
                );
            }
        }
    };

    global.YUKA = {
        Vector3,
        Quaternion,
        Path,
        GameEntity,
        MovingEntity,
        Vehicle,
        EntityManager,
        SyncManager,
        SteeringBehavior,
        SeekBehavior,
        FleeBehavior,
        ArriveBehavior,
        PursueBehavior,
        EvadeBehavior,
        WanderBehavior,
        SeparationBehavior,
        AlignmentBehavior,
        CohesionBehavior,
        ObstacleAvoidanceBehavior,
        FollowPathBehavior,
        SteeringManager,
        Vision,
        MemoryRecord,
        MemorySystem,
        State,
        StateMachine,
        Goal,
        GoalStatus,
        CompositeGoal,
        GoalEvaluator,
        Think,
        NavMesh
    };
})(window);
